import { readFile, writeFile } from 'fs/promises';

async function logVisit() {
  try {
    // Read an existing log file, or start with an empty string if it doesn't exist yet
    let existingLog = '';
    try {
      existingLog = await readFile('visits.log', 'utf-8');
    } catch (err) {
      // file doesn't exist yet on the first run - that's fine
    }

    const newEntry = `Visit recorded at ${new Date().toISOString()}\n`;
    await writeFile('visits.log', existingLog + newEntry);

    console.log('Visit logged successfully.');
  } catch (err) {
    console.error('Failed to log visit:', err.message);
  }
}

logVisit();

