// app.js
import { readFile, writeFile } from 'fs/promises';

const newName = 'Jordan';

async function addName() {
  let names = [];

  try {
    const fileContents = await readFile('names.json', 'utf-8');
    names = JSON.parse(fileContents);
  } catch (err) {
    // file doesn't exist yet - start with an empty array
  }

  names.push(newName);

  try {
    await writeFile('names.json', JSON.stringify(names, null, 2));
    console.log('Name added successfully.');
  } catch (err) {
    console.error('Failed to write file:', err.message);
  }
}

addName();

sections.content:
After running npm install express (introduced in lesson 2):

import express from 'express';

const app = express();
const PORT = 3000;

app.get('/', (req, res) => {
  res.send('Hello, world!');
});

app.get('/about', (req, res) => {
  res.send('This is the about page.');
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

Key pieces:
- express() creates a new Express application instance
- app.get(path, handler) registers a route: when a GET request arrives at exactly this path, run this specific handler function
- Every handler function receives req (the incoming request object, with details like URL parameters, query strings, and the request body) and res (the response object, used to send data back)
- res.send(...) sends a response back to the client and completes that request-response cycle
- app.listen(port, callback) starts the server, making it actually listen for incoming connections on the specified port

