import express from 'express';

const app = express();
app.use(express.json()); // enables req.body parsing for JSON request bodies

let reviews = [
  { id: 1, productId: 101, rating: 5, comment: 'Great product!' },
  { id: 2, productId: 101, rating: 3, comment: 'It was okay.' },
  { id: 3, productId: 102, rating: 4, comment: 'Pretty good.' }
];

// Route parameter (:productId) identifies WHICH product's reviews,
// query parameter (minRating) optionally filters them
app.get('/products/:productId/reviews', (req, res) => {
  const productId = Number(req.params.productId);
  const minRating = req.query.minRating ? Number(req.query.minRating) : 0;

  const filtered = reviews.filter(
    (r) => r.productId === productId && r.rating >= minRating
  );

  res.json({ success: true, data: filtered });
});

// Request body carries the substantial new data for a new review
app.post('/products/:productId/reviews', (req, res) => {
  const productId = Number(req.params.productId);
  const { rating, comment } = req.body;

  const newReview = {
    id: reviews.length + 1,
    productId,
    rating,
    comment
  };
  reviews.push(newReview);

  res.status(201).json({ success: true, data: newReview });
});

