import express from 'express';

const app = express();
app.use(express.json());

let tasks = [
  { id: 1, title: 'Buy groceries', completed: false },
  { id: 2, title: 'Write report', completed: true }
];
let nextId = 3;

// GET /tasks - retrieve all tasks
app.get('/tasks', (req, res) => {
  res.json({ success: true, data: tasks });
});

// GET /tasks/:id - retrieve one specific task
app.get('/tasks/:id', (req, res) => {
  const task = tasks.find((t) => t.id === Number(req.params.id));
  if (!task) return res.status(404).json({ success: false, error: 'Task not found' });
  res.json({ success: true, data: task });
});

// POST /tasks - create a new task
app.post('/tasks', (req, res) => {
  const newTask = { id: nextId++, title: req.body.title, completed: false };
  tasks.push(newTask);
  res.status(201).json({ success: true, data: newTask });
});

// PATCH /tasks/:id - partially update a task (e.g. just toggling completed)
app.patch('/tasks/:id', (req, res) => {
  const task = tasks.find((t) => t.id === Number(req.params.id));
  if (!task) return res.status(404).json({ success: false, error: 'Task not found' });

  Object.assign(task, req.body); // merges only the provided fields in
  res.json({ success: true, data: task });
});

// DELETE /tasks/:id - delete a specific task
app.delete('/tasks/:id', (req, res) => {
  const index = tasks.findIndex((t) => t.id === Number(req.params.id));
  if (index === -1) return res.status(404).json({ success: false, error: 'Task not found' });

  tasks.splice(index, 1);
  res.status(204).send(); // 204 No Content: success, with nothing further to return
});

