import express from 'express';

const app = express();
app.use(express.json());

let tasks = [{ id: 1, title: 'Buy groceries', completed: false }];
let nextId = 2;

function validateTitle(title) {
  return typeof title === 'string' && title.trim() !== '';
}

// CREATE - validate before adding anything
app.post('/tasks', (req, res) => {
  const { title } = req.body;

  if (!validateTitle(title)) {
    return res.status(400).json({ success: false, error: 'A non-empty title is required' });
  }

  const newTask = { id: nextId++, title: title.trim(), completed: false };
  tasks.push(newTask);
  res.status(201).json({ success: true, data: newTask });
});

// READ - no validation needed for reading, but still check existence
app.get('/tasks/:id', (req, res) => {
  const task = tasks.find((t) => t.id === Number(req.params.id));
  if (!task) return res.status(404).json({ success: false, error: 'Task not found' });
  res.json({ success: true, data: task });
});

// UPDATE - validate existence AND validate any provided new data
app.patch('/tasks/:id', (req, res) => {
  const task = tasks.find((t) => t.id === Number(req.params.id));
  if (!task) return res.status(404).json({ success: false, error: 'Task not found' });

  if (req.body.title !== undefined && !validateTitle(req.body.title)) {
    return res.status(400).json({ success: false, error: 'Title cannot be empty' });
  }

  Object.assign(task, req.body);
  res.json({ success: true, data: task });
});

// DELETE - validate existence before attempting removal
app.delete('/tasks/:id', (req, res) => {
  const index = tasks.findIndex((t) => t.id === Number(req.params.id));
  if (index === -1) return res.status(404).json({ success: false, error: 'Task not found' });
  tasks.splice(index, 1);
  res.status(204).send();
});

