sections.content:
Middleware function signature: (req, res, next) => { ... } — three parameters, where next is a function that, when called, hands control to whatever's registered next in the sequence.

// Applied globally, to every single request:
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path}`);
  next(); // MUST be called, or the request will hang forever
});

// Applied only to specific routes, by passing it as an extra argument:
function requireApiKey(req, res, next) {
  if (req.headers['x-api-key'] !== 'secret123') {
    return res.status(401).json({ success: false, error: 'Invalid API key' });
  }
  next();
}

app.get('/admin/stats', requireApiKey, (req, res) => {
  res.json({ success: true, data: { userCount: 42 } });
});

In the second example, requireApiKey runs before the route's own handler, but ONLY for this specific route, not for every request to the entire application — a middleware function can be scoped as broadly (app.use(), applying to everything) or as narrowly (passed to one specific route) as the situation calls for.

sections.code:
import express from 'express';

const app = express();

// GLOBAL middleware: runs for every single request, no exceptions
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

app.use(express.json());

// ROUTE-SPECIFIC middleware: only applies where explicitly listed
function requireAuth(req, res, next) {
  const token = req.headers.authorization;

  if (!token) {
    // Short-circuits here: sends a response directly, next() is never called,
    // so this request never reaches the actual route handler below
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }

  req.userId = 42; // middleware can attach new data onto req for later stages to use
  next(); // only reached if a token was present
}

app.get('/public-info', (req, res) => {
  res.json({ success: true, data: 'Anyone can see this' });
});

app.get('/account', requireAuth, (req, res) => {
  // req.userId is available here because requireAuth ran first and attached it
  res.json({ success: true, data: { userId: req.userId, balance: 100 } });
});

app.listen(3000);

