import express from 'express';

const app = express();
app.use(express.json());

// A custom error class lets route handlers throw errors with a specific,
// intentional status code attached, rather than always defaulting to 500
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.status = 404;
  }
}

const tasks = [{ id: 1, title: 'Buy groceries' }];

async function findTaskOrThrow(id) {
  const task = tasks.find((t) => t.id === Number(id));
  if (!task) {
    throw new NotFoundError(`Task with id ${id} not found`);
  }
  return task;
}

app.get('/tasks/:id', async (req, res, next) => {
  try {
    const task = await findTaskOrThrow(req.params.id);
    res.json({ success: true, data: task });
  } catch (err) {
    next(err); // forward ANY error - expected or unexpected - to the centralized handler
  }
});

// Centralized error-handling middleware - MUST be registered last,
// after every other route and middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  const status = err.status || 500; // default to 500 for unexpected errors
  res.status(status).json({
    success: false,
    error: err.message || 'An unexpected error occurred'
  });
});

app.listen(3000);

