import express from 'express';

const app = express();
app.use(express.json());

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.status = 400;
  }
}

class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.status = 404;
  }
}

const items = [{ id: 1, name: 'Widget' }];
let nextId = 2;

app.get('/items/:id', async (req, res, next) => {
  try {
    const item = items.find((i) => i.id === Number(req.params.id));
    if (!item) throw new NotFoundError('Item not found');
    res.json({ success: true, data: item });
  } catch (err) {
    next(err);
  }
});

app.post('/items', async (req, res, next) => {
  try {
    if (!req.body.name) throw new ValidationError('name is required');
    const newItem = { id: nextId++, name: req.body.name };
    items.push(newItem);
    res.status(201).json({ success: true, data: newItem });
  } catch (err) {
    next(err);
  }
});

app.use((err, req, res, next) => {
  const status = err.status || 500;
  res.status(status).json({ success: false, error: err.message || 'Unexpected error' });
});

app.listen(3000);

