// AUDIT AGAINST THE 5 CHECKS:
// 1. Trust boundary: FAILS - verifiedPurchase is trusted directly from the
//    client; a user could claim a verified purchase that never happened.
//    This should be looked up server-side from actual order records instead.
// 2. REST consistency: mostly OK (resource-based URL, POST for creation),
//    but the response isn't wrapped in the { success, data } shape used
//    elsewhere in this API.
// 3. CRUD validation: FAILS - no validation at all on rating or productId;
//    a missing or malformed rating would be silently accepted and stored.
// 4. Lifecycle/middleware: OK, assuming express.json() is registered earlier.
// 5. Error handling: FAILS - no try/catch, no next(err), and no error
//    response path at all if anything unexpected occurs.

// CORRECTED VERSION, addressing all 5 gaps:
app.post('/reviews', async (req, res, next) => {
  try {
    const { productId, rating, authorName } = req.body;

    if (!productId || typeof rating !== 'number' || rating < 1 || rating > 5) {
      throw new ValidationError('productId and a rating between 1-5 are required');
    }

    const verifiedPurchase = await checkVerifiedPurchase(productId, authorName); // looked up server-side, never trusted from the client

    const review = { id: Date.now(), productId, rating, authorName, verifiedPurchase };
    reviews.push(review);
    res.status(201).json({ success: true, data: review });
  } catch (err) {
    next(err);
  }
});

