// AUDIT:
// 1. Trust boundary: FAILS - req.body.newBalance is trusted directly from
//    the client, letting a user set their balance to anything they want.
// 2. REST consistency: questionable - POST for an update is more PATCH-like;
//    also no consistent { success, data } response shape used.
// 3. CRUD validation: FAILS - no check that the account exists before use,
//    no validation on the incoming amount/type at all.
// 4. Lifecycle/middleware: assume OK if express.json() is registered earlier.
// 5. Error handling: FAILS - no try/catch, no next(err), and accessing
//    .balance on a possibly-undefined account would throw an unhandled error.

// CORRECTED VERSION:
app.patch('/accounts/:id/balance', async (req, res, next) => {
  try {
    const account = accounts.find((a) => a.id === Number(req.params.id));
    if (!account) throw new NotFoundError('Account not found');

    const { amount, type } = req.body;
    if (typeof amount !== 'number' || !['deposit', 'withdrawal'].includes(type)) {
      throw new ValidationError('A numeric amount and a valid type are required');
    }

    account.balance = calculateCorrectBalance(account, amount, type); // calculated server-side, never trusted from client
    res.json({ success: true, data: account });
  } catch (err) {
    next(err);
  }
});
